  "name": "@stallion/schema",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "dependencies": {
    "ajv": "^8.20.0",
    "cbor-x": "^1.6.6",
    "zod": "^4.6.5"
  },
  "scripts": {
    "generate": "vitest run --update"
  }
