.swatch[aria-pressed="true"] {
  border-color: transparent;
}

.swatch[aria-pressed="true"] .swatch-fill,
.swatch.current .swatch-fill {
  box-shadow:
    inset 0 0 0 2px var(--panel),
    0 0 0 2px var(--panel),
    0 0 0 4px var(--ink);
}

.swatch.secondary::after {
  content: "";
  position: absolute;
  right: 3px;
  bottom: 3px;
  width: 10px;
  height: 10px;
  border: 2px solid var(--panel);
  border-radius: 50%;
  color: #60646c;
}

.landing-alert {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid #e5484d;
  background: #fff5f5;
  color: #8a1c1f;
}

.landing-alert p {
  margin: 0;
}

.toolbar[data-layout="Palette"] {
  right: auto;
  margin: 0;
  max-width: none;
  padding: 6px;
}

.toolbar[data-layout="Palette"] .toolbar-row,
.toolbar[data-layout="Palette"] .group {
  display: grid;
  grid-template-columns: repeat(var(--palette-columns, 2), 44px);
  justify-items: center;
  align-items: center;
  gap: 4px;
}

.toolbar[data-layout="Palette"] .group {
  grid-column: 1 / -1;
}

.toolbar[data-layout="Expanded"] .toolbar-row {
  align-self: stretch;
}

.toolbar[data-layout="Expanded"] .toolbar-row + .toolbar-row,
.toolbar[data-layout="Palette"] .toolbar-row + .toolbar-row {
  padding-top: 4px;
  border-top: 1px solid var(--line);
}

.toolbar[data-layout="Palette"] .level-chip {
  width: 44px;
  min-width: 0;
  padding: 0;
  font-size: 14px;
}

.toolbar[data-layout="Palette"] .level-list {
  top: 0;
  right: auto;
  left: calc(100% + 10px);
}

.toolbar[data-layout="Palette"] .level-list[data-side="Above"] {
  top: auto;
  bottom: 0;
}

@media (max-height: 640px) {
  .toolbar[data-layout="Palette"] {
