cat > ~/development/.tmp/stallion-rgb/proof.mjs <<'EOF'
import { writeFileSync, readFileSync } from "node:fs";
import { chromium, devices } from "/home/mvhenten/development/stallion-worktrees/rgb/node_modules/playwright/index.mjs";
import { routeAccessHeaders } from "/home/mvhenten/development/stallion-worktrees/rgb/npm-scripts/env.mjs";
const ORIGIN = "https://stallion.kattebak.fyi";
const DIR = "/home/mvhenten/development/.tmp/stallion-rgb";
const [newBoard, ...legacy] = process.argv.slice(2);
const PALETTE = [0x1f2328, 0xe5484d, 0xf76b15, 0x30a46c, 0x0090ff, 0x8e4ec6];
const browser = await chromium.launch({ headless: true });
const profiles = { phone: devices["Pixel 7"], tablet: devices["Galaxy Tab S9"] };
const counts = async (page, png) => page.evaluate(async ([b64, pal]) => {
  const bytes = Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
  const bm = await createImageBitmap(new Blob([bytes], { type: "image/png" }));
  const c = new OffscreenCanvas(bm.width, bm.height); const x = c.getContext("2d"); x.drawImage(bm, 0, 0);
  const d = x.getImageData(0, 0, bm.width, bm.height).data;
  const out = pal.map(() => 0);
  for (let i = 0; i < d.length; i += 4) pal.forEach((p, k) => {
    if (Math.abs(d[i] - (p >> 16)) + Math.abs(d[i + 1] - ((p >> 8) & 255)) + Math.abs(d[i + 2] - (p & 255)) <= 12) out[k]++;
  });
  return out;
}, [png.toString("base64"), pal]);
let pal = PALETTE;
const results = [];
for (const [name, device] of Object.entries(profiles)) {
  const context = await browser.newContext({ ...device, colorScheme: "light" });
  await routeAccessHeaders(context, ORIGIN);
  const page = await context.newPage();
  const errors = [];
  page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
  page.on("pageerror", (e) => errors.push(e.message));
  for (const [label, id] of [["new", newBoard], ...legacy.map((id) => ["legacy", id])]) {
    await page.goto(`${ORIGIN}/b/${id}`, { waitUntil: "load" });
    await page.locator("canvas.surface").waitFor({ state: "visible", timeout: 15000 });
    await page.waitForTimeout(2500);
    if (label === "new") {
      const flip = page.locator('.toolbar:not([data-layout="Palette"]) [data-toolbar-flip]');
      const more = page.getByRole("button", { name: "More tools" });
      if (await more.isVisible()) await more.tap();
      if (await flip.isVisible()) await flip.tap();
      await page.waitForTimeout(500);
    }
    const png = await page.screenshot();
    const path = `${DIR}/${name}-${label}-${id}.png`;
    writeFileSync(path, png);
    pal = label === "new" ? [...PALETTE, 0x123456] : PALETTE;
    results.push({ name, label, id, path, pixels: await counts(page, png) });
  }
  results.push({ name, errors });
  await context.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 1));
EOF
